use std::collections::HashSet;

fn has_common_element(a: Vec<i32>, b: Vec<i32>) -> bool {
    // Fast exits for empty inputs
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // Build a set from the smaller array to reduce memory usage
    let (small, large) = if a.len() <= b.len() { (a, b) } else { (b, a) };

    let set: HashSet<i32> = small.into_iter().collect();

    // Check whether any element from the other array exists in the set
    large.into_iter().any(|x| set.contains(&x))
}

